<script setup>
import { ref, watch, onBeforeUnmount } from 'vue';
import { ccCore } from '../../api/cc-core';
import { apiUrl } from '../../api/config';
import { downloadCsv } from '../../lib/cc';
const props=defineProps({from:String,to:String,title:{type:String,default:'Agent 360 · Lead Journey'},showFullReport:{type:Boolean,default:true}});const emit=defineEmits(['open']);
const data=ref(null),busy=ref(false),error=ref(''),fullReport=ref(false);let generation=0;
const source=apiUrl('/branch-visit-report-CC-LEAD-REPORTS#a360');
async function load(){const token=++generation;busy.value=true;error.value='';data.value=null;try{const result=await ccCore('report',{from_date:props.from,to_date:props.to});if(token===generation)data.value=result;}catch(e){if(token===generation)error.value=e.message;}finally{if(token===generation)busy.value=false;}}
watch(()=>[props.from,props.to],load,{immediate:true});onBeforeUnmount(()=>generation++);
function exportAgents(){downloadCsv('cc-agent-360.csv',[{key:'name',label:'Agent'},...['leads','contacted','booked','visited','joined','paid','unreach3','overdue'].map(key=>({key,label:key}))],data.value.agents);}
</script>
<template><section class="card"><header class="card-hdr">{{title}} <button class="btn btn-gy btn-sm" :disabled="busy" @click="load">Refresh</button><button class="btn btn-gy btn-sm" :disabled="!data||data.capped" @click="exportAgents">Export</button></header><div class="card-body"><p v-if="busy" role="status">Loading Agent 360…</p><p v-if="error" role="alert" class="cc-error">{{error}}</p><template v-if="data"><p v-if="data.capped" class="cc-error">This range reached the report limit. Choose a shorter range.</p><div class="cc-report-metrics"><div v-for="(value,key) in data.funnel" :key="key"><strong>{{key==='paid'?'₹':''}}{{Number(value).toLocaleString('en-IN')}}</strong><span>{{key.replaceAll('_',' ')}}</span></div></div><div class="tbl-wrap"><table><thead><tr><th>Agent</th><th>Leads</th><th>Contacted</th><th>Appointments</th><th>Visited</th><th>Joined</th><th>Paid</th><th>Unreachable 3+</th><th>Overdue</th></tr></thead><tbody><tr v-for="a in data.agents" :key="a.agent"><td>{{a.name}}</td><td>{{a.leads}}</td><td>{{a.contacted}}</td><td>{{a.booked}}</td><td>{{a.visited}}</td><td>{{a.joined}}</td><td>₹{{a.paid.toLocaleString('en-IN')}}</td><td>{{a.unreach3}}</td><td>{{a.overdue}}</td></tr></tbody></table></div><details><summary>Last call results</summary><p v-for="(count,result) in data.last_call_mix" :key="result">{{result}}: {{count}}</p></details><details><summary>Joined clients and conversion credit</summary><div class="tbl-wrap"><table><thead><tr><th>Lead</th><th>Owner</th><th>Joined</th><th>Paid</th><th>Credit</th></tr></thead><tbody><tr v-for="row in data.joined" :key="row.lead"><td><button class="btn btn-gy btn-sm" @click="emit('open',row.lead)">{{row.lead}}</button></td><td>{{row.owner}}</td><td>{{row.joined_on}}</td><td>₹{{row.paid}}</td><td>{{row.credit_name}}</td></tr></tbody></table></div></details><details><summary>Lead moves and verification history</summary><p v-for="(row,i) in data.moves" :key="i">{{row.event_time}} · {{row.lead}} · {{row.action}} · {{row.old_status}} → {{row.new_status}} · {{row.erp_user}}</p></details></template><button v-if="showFullReport" class="btn btn-gy" @click="fullReport=!fullReport">{{fullReport?'Hide':'Open'}} ERP + ConVox + Mobile report</button><a v-if="showFullReport" :href="source" target="_blank" rel="noopener">Open full screen ↗</a><iframe v-if="fullReport" :src="source" title="Agent 360 ERP ConVox and Mobile report" class="cc-agent-frame"></iframe></div></section></template>
<style scoped>.cc-agent-frame{display:block;width:100%;height:75vh;min-height:520px;border:1px solid #e3dccb;margin-top:12px}details{padding:12px 0}a{margin-left:12px}</style>
